List<Long> firstSuspiciousForeign(List<Payment> feed, ToIntFunction<Payment> riskScore, int n) {
    return feed.stream()
            .filter(p -> !p.country().equals("NL"))      // cheap check first
            .filter(p -> riskScore.applyAsInt(p) >= 90)
            .map(Payment::id)                             // boxed Long, as in Kotlin
            .limit(n)                                     // short-circuits like take(n)
            .toList();                                    // unmodifiable on JDK 16+
}

