fun <T> paged(fetch: (Int) -> List<T>): Sequence<T> = sequence {
    var page = 1
    while (true) {
        val items = fetch(page++)      // runs only when the consumer asks for more
        if (items.isEmpty()) break     // an empty page ends it
        yieldAll(items)                // pauses here between elements
    }
}

