static <T> Stream<T> paged(IntFunction<List<T>> fetch) {
    return Stream.iterate(1, page -> page + 1)       // 1, 2, 3, ... lazily
            .map(fetch::apply)                       // one fetch per page, on demand
            .takeWhile(items -> !items.isEmpty())    // stops at the first empty page
            .flatMap(List::stream);
}
